import { Component } from "react"

class Car extends Component{

    fan='123'
items=[{
    name: 'audi',
    price: 10000
},
{
    name: 'bmw',
    price: 20000
},
{
    name: 'merc',
    price: 30000
}
]

    constructor(){
        super()
        this.love= 'family'
    }
    render(){
        return<>
        <h1>hello {this.love} {this.fan}</h1>
        </>
    }
}

export default Car;
